@namespace sv_7bab033cc4d74388af10c578d24ce848.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => OnStepClick(stepIndex)" role="button" tabindex="0">
                <span class="step-badge">
                    @if (status == "completed")
                    {
                        <span class="checkmark">✓</span>
                    }
                    else
                    {
                        @(stepIndex + 1)
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnNavigateToStep { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepStatus(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < CurrentStep) return "completed";
        return "future";
    }

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnNavigateToStep.InvokeAsync(step);
        }
    }
}

@namespace sv_7bab033cc4d74388af10c578d24ce848.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error" role="alert">@ErrorMessage</div>
    }

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" @bind="FullName" @bind:event="oninput" placeholder="John Doe" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" placeholder="john@example.com" />
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" @bind="Phone" @bind:event="oninput" placeholder="(555) 123-4567" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <input id="address" type="text" @bind="Address" @bind:event="oninput" placeholder="123 Main St, City, State" />
    </div>

    <div class="step-buttons">
        <button class="btn-next" @onclick="HandleNext" disabled="@IsValidating">
            @if (IsValidating)
            {
                <span>Validating...</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<(string FullName, string Email, string Phone, string Address)> OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string ErrorMessage = "";
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = "";

        if (string.IsNullOrWhiteSpace(FullName))
        {
            ErrorMessage = "Full name is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Email))
        {
            ErrorMessage = "Email is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Phone))
        {
            ErrorMessage = "Phone is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "Address is required.";
            return;
        }

        IsValidating = true;
        try
        {
            var isValid = await ValidateEmail(Email);
            if (!isValid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }
        }
        finally
        {
            IsValidating = false;
        }

        await OnNext.InvokeAsync((FullName, Email, Phone, Address));
    }
}

@namespace sv_7bab033cc4d74388af10c578d24ce848.Components.Pages.Apply

<fieldset class="work-entry-form">
    <legend>Position @(Index + 1)</legend>

    @if (ShowRemove)
    {
        <button class="btn-remove" @onclick="() => OnRemove.InvokeAsync(Index)" type="button">Remove</button>
    }

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="e => Update(e, nameof(Entry.Company))" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="e => Update(e, nameof(Entry.Title))" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="e => UpdateStartDate(e)" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? "")" @onchange="e => UpdateEndDate(e)" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="ToggleCurrent" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description" @onchange="e => Update(e, nameof(Entry.Description))"></textarea>
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<int> OnRemove { get; set; }
    [Parameter] public EventCallback<(int Index, WorkEntryModel Entry)> OnEntryChanged { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private void Update(ChangeEventArgs e, string field)
    {
        var value = e.Value?.ToString() ?? "";
        var updated = field switch
        {
            nameof(Entry.Company) => Entry with { Company = value },
            nameof(Entry.Title) => Entry with { Title = value },
            nameof(Entry.Description) => Entry with { Description = value },
            _ => Entry
        };
        OnEntryChanged.InvokeAsync((Index, updated));
    }

    private void UpdateStartDate(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date))
        {
            OnEntryChanged.InvokeAsync((Index, Entry with { StartDate = date }));
        }
    }

    private void UpdateEndDate(ChangeEventArgs e)
    {
        DateTime? date = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null;
        OnEntryChanged.InvokeAsync((Index, Entry with { EndDate = date }));
    }

    private void ToggleCurrent(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        OnEntryChanged.InvokeAsync((Index, updated));
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

@namespace sv_7bab033cc4d74388af10c578d24ce848.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error" role="alert">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       ShowRemove="@(Entries.Count > 1)"
                       OnRemove="RemoveEntry"
                       OnEntryChanged="UpdateEntry" />
    }

    <button class="btn-add" @onclick="AddEntry" type="button">+ Add Another Position</button>

    <div class="step-buttons">
        <button class="btn-back" @onclick="OnBack">Back</button>
        <button class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryForm.WorkEntryModel> Entries { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryForm.WorkEntryModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string ErrorMessage = "";

    protected override void OnParametersSet()
    {
        if (Entries.Count == 0)
        {
            Entries = new List<WorkEntryForm.WorkEntryModel> { new() };
        }
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntryForm.WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private void UpdateEntry((int Index, WorkEntryForm.WorkEntryModel Entry) args)
    {
        Entries[args.Index] = args.Entry;
    }

    private async Task HandleNext()
    {
        ErrorMessage = "";
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position requires at least a company name and job title.";
                return;
            }
        }
        await OnNext.InvokeAsync(Entries);
    }
}

@namespace sv_7bab033cc4d74388af10c578d24ce848.Components.Pages.Apply

<fieldset class="reference-form">
    <legend>Reference @(Index + 1)</legend>

    @if (ShowRemove)
    {
        <button class="btn-remove" @onclick="() => OnRemove.InvokeAsync(Index)" type="button">Remove</button>
    }

    <div class="form-group">
        <label>Name *</label>
        <input type="text" value="@Entry.Name" @onchange="e => Update(e, nameof(Entry.Name))" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" value="@Entry.Relationship" @onchange="e => Update(e, nameof(Entry.Relationship))" placeholder="e.g., Former Manager" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" value="@Entry.Email" @onchange="e => Update(e, nameof(Entry.Email))" />
        </div>
        <div class="form-group">
            <label>Phone</label>
            <input type="tel" value="@Entry.Phone" @onchange="e => Update(e, nameof(Entry.Phone))" />
        </div>
    </div>
</fieldset>

@code {
    [Parameter, EditorRequired] public ReferenceModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<int> OnRemove { get; set; }
    [Parameter] public EventCallback<(int Index, ReferenceModel Entry)> OnEntryChanged { get; set; }

    private void Update(ChangeEventArgs e, string field)
    {
        var value = e.Value?.ToString() ?? "";
        var updated = field switch
        {
            nameof(Entry.Name) => Entry with { Name = value },
            nameof(Entry.Relationship) => Entry with { Relationship = value },
            nameof(Entry.Email) => Entry with { Email = value },
            nameof(Entry.Phone) => Entry with { Phone = value },
            _ => Entry
        };
        OnEntryChanged.InvokeAsync((Index, updated));
    }

    public record ReferenceModel
    {
        public string Name { get; init; } = "";
        public string Relationship { get; init; } = "";
        public string Email { get; init; } = "";
        public string Phone { get; init; } = "";
    }
}

@namespace sv_7bab033cc4d74388af10c578d24ce848.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error" role="alert">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Entry="@References[index]"
                       Index="index"
                       ShowRemove="@(References.Count > 2)"
                       OnRemove="RemoveReference"
                       OnEntryChanged="UpdateReference" />
    }

    @if (References.Count < 3)
    {
        <button class="btn-add" @onclick="AddReference" type="button">+ Add Reference</button>
    }

    <div class="step-buttons">
        <button class="btn-back" @onclick="OnBack">Back</button>
        <button class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceForm.ReferenceModel> References { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<ReferenceForm.ReferenceModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string ErrorMessage = "";

    protected override void OnParametersSet()
    {
        if (References.Count == 0)
        {
            References = new List<ReferenceForm.ReferenceModel> { new(), new() };
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceForm.ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private void UpdateReference((int Index, ReferenceForm.ReferenceModel Entry) args)
    {
        References[args.Index] = args.Entry;
    }

    private async Task HandleNext()
    {
        ErrorMessage = "";
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) || string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Each reference requires a name, relationship, and email.";
                return;
            }
        }
        await OnNext.InvokeAsync(References);
    }
}

