+@namespace sv_7bab033cc4d74388af10c578d24ce848.Components.Pages.Apply
+
+<div class="step-content">
+    <h2>References</h2>
+
+    @if (!string.IsNullOrEmpty(ErrorMessage))
+    {
+        <div class="validation-error" role="alert">@ErrorMessage</div>
+    }
+
+    @for (int i = 0; i < References.Count; i++)
+    {
+        var index = i;
+        <ReferenceForm Entry="@References[index]"
+                       Index="index"
+                       ShowRemove="@(References.Count > 2)"
+                       OnRemove="RemoveReference"
+                       OnEntryChanged="UpdateReference" />
+    }
+
+    @if (References.Count < 3)
+    {
+        <button class="btn-add" @onclick="AddReference" type="button">+ Add Reference</button>
+    }
+
+    <div class="step-buttons">
+        <button class="btn-back" @onclick="OnBack">Back</button>
+        <button class="btn-next" @onclick="HandleNext">Next</button>
+    </div>
+</div>
+
+@code {
+    [Parameter] public List<ReferenceForm.ReferenceModel> References { get; set; } = new();
+    [Parameter, EditorRequired] public EventCallback<List<ReferenceForm.ReferenceModel>> OnNext { get; set; }
+    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
+
+    private string ErrorMessage = "";
+
+    protected override void OnParametersSet()
+    {
+        if (References.Count == 0)
+        {
+            References = new List<ReferenceForm.ReferenceModel> { new(), new() };
+        }
+    }
+
+    private void AddReference()
+    {
+        if (References.Count < 3)
+        {
+            References.Add(new ReferenceForm.ReferenceModel());
+        }
+    }
+
+    private void RemoveReference(int index)
+    {
+        if (References.Count > 2)
+        {
+            References.RemoveAt(index);
+        }
+    }
+
+    private void UpdateReference((int Index, ReferenceForm.ReferenceModel Entry) args)
+    {
+        References[args.Index] = args.Entry;
+    }
+
+    private async Task HandleNext()
+    {
+        ErrorMessage = "";
+        foreach (var r in References)
+        {
+            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) || string.IsNullOrWhiteSpace(r.Email))
+            {
+                ErrorMessage = "Each reference requires a name, relationship, and email.";
+                return;
+            }
+        }
+        await OnNext.InvokeAsync(References);
+    }
+}
