@page "/apply"
@namespace sv_7bab033cc4d74388af10c578d24ce848.Components.Pages.Apply
@using sv_7bab033cc4d74388af10c578d24ce848.Services
@rendermode InteractiveServer

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" OnNavigateToStep="NavigateToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                              OnNext="HandlePersonalInfoNext" ValidateEmail="ApplicationService.ValidateEmailAsync" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries" OnNext="HandleWorkHistoryNext" OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="@references" OnNext="HandleReferencesNext" OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter" OnNext="HandleCoverLetterNext" OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                        WorkEntries="@workEntries" References="@references" CoverLetter="@coverLetter"
                        OnEditSection="NavigateToStep" OnBack="GoBack" OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep = 0;

    // Step 1 state
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 state
    private List<WorkEntryForm.WorkEntryModel> workEntries = new() { new() };

    // Step 3 state
    private List<ReferenceForm.ReferenceModel> references = new() { new(), new() };

    // Step 4 state
    private string coverLetter = "";

    private void NavigateToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0) currentStep--;
    }

    private void HandlePersonalInfoNext((string FullName, string Email, string Phone, string Address) data)
    {
        fullName = data.FullName;
        email = data.Email;
        phone = data.Phone;
        address = data.Address;
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        currentStep = 4;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new Models.JobApplication(
            new Models.PersonalInfo(fullName, email, phone, address),
            new Models.WorkHistory(workEntries.Select(e => new Models.WorkEntry(
                e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description
            )).ToList()),
            references.Select(r => new Models.Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

