.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-badge {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
    border: 2px solid #ddd;
    background: #f5f5f5;
    color: #999;
    transition: all 0.2s;
}

.step-item.active .step-badge {
    background: #2563eb;
    border-color: #2563eb;
    color: white;
}

.step-item.completed .step-badge {
    background: #16a34a;
    border-color: #16a34a;
    color: white;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #999;
}

.step-item.active .step-label {
    color: #2563eb;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #16a34a;
}

.checkmark {
    font-size: 1rem;
}

/* Step Content */
.step-content {
    background: white;
    border: 1px solid #e5e7eb;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.35rem;
    font-weight: 500;
    color: #374151;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #2563eb;
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.5rem;
    font-weight: normal !important;
    font-size: 0.85rem !important;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e5e7eb;
}

.btn-next, .btn-submit {
    padding: 0.7rem 2rem;
    background: #2563eb;
    color: white;
    border: none;
    border-radius: 6px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    margin-left: auto;
    transition: background 0.2s;
}

.btn-next:hover, .btn-submit:hover {
    background: #1d4ed8;
}

.btn-next:disabled, .btn-submit:disabled {
    background: #93c5fd;
    cursor: not-allowed;
}

.btn-back {
    padding: 0.7rem 2rem;
    background: white;
    color: #374151;
    border: 1px solid #d1d5db;
    border-radius: 6px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background 0.2s;
}

.btn-back:hover {
    background: #f9fafb;
}

.btn-add {
    padding: 0.5rem 1rem;
    background: #f0fdf4;
    color: #16a34a;
    border: 1px dashed #16a34a;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    margin-top: 1rem;
    transition: background 0.2s;
}

.btn-add:hover {
    background: #dcfce7;
}

.btn-remove {
    float: right;
    padding: 0.3rem 0.8rem;
    background: #fef2f2;
    color: #dc2626;
    border: 1px solid #fecaca;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
}

.btn-remove:hover {
    background: #fee2e2;
}

.btn-edit {
    padding: 0.3rem 0.8rem;
    background: transparent;
    color: #2563eb;
    border: 1px solid #2563eb;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
}

.btn-edit:hover {
    background: #eff6ff;
}

/* Fieldsets */
fieldset {
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

fieldset legend {
    font-weight: 600;
    color: #374151;
    padding: 0 0.5rem;
}

/* Character Count */
.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #6b7280;
    margin-top: 0.5rem;
}

.char-count.warning {
    color: #dc2626;
    font-weight: 500;
}

/* Validation */
.validation-error {
    background: #fef2f2;
    border: 1px solid #fecaca;
    color: #dc2626;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

/* Review */
.review-section {
    border: 1px solid #e5e7eb;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    color: #1a1a2e;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #6b7280;
}

.review-section dd {
    margin: 0;
    color: #1f2937;
}

.review-item {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f3f4f6;
}

.review-item:last-child {
    border-bottom: none;
}

.date-range {
    font-size: 0.85rem;
    color: #6b7280;
}

.cover-letter-preview {
    white-space: pre-wrap;
    color: #374151;
    line-height: 1.6;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 2rem;
    background: #f0fdf4;
    border: 1px solid #bbf7d0;
    border-radius: 8px;
}

.submission-confirmation h3 {
    color: #16a34a;
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.submission-confirmation p {
    color: #374151;
    font-size: 1.1rem;
}

.btn-submit {
    background: #16a34a;
}

.btn-submit:hover {
    background: #15803d;
}

.btn-submit:disabled {
    background: #86efac;
}

